73	export function getDominantTimeblock(record: Tier3StateRecord | ChannelStateRecord): string | null {
74	  const arcCounts = [
75	    { key: 'timeblock_arc0', count: record.timeblock_arc0 },
76	    { key: 'timeblock_arc1', count: record.timeblock_arc1 },
77	    { key: 'timeblock_arc2', count: record.timeblock_arc2 },
78	    { key: 'timeblock_arc3', count: record.timeblock_arc3 },
79	    { key: 'timeblock_arc4', count: record.timeblock_arc4 },
80	  ];
81	  arcCounts.sort((a, b) => b.count - a.count);
82	  const highest = arcCounts[0];
83	  return highest && highest.count > 0 ? ARC_METADATA[highest.key]?.title || null : null;
84	}
