86	function parseJsonArray(val: unknown): string[] {
87	  if (Array.isArray(val)) return val;
88	  if (typeof val === 'string' && val.trim() !== '') {
89	    try {
90	      const parsed = JSON.parse(val);
91	      return Array.isArray(parsed) ? parsed : [];
92	    } catch {
93	      return [];
94	    }
95	  }
96	  return [];
97	}
