136	export async function rateChannelDirect(
137	  projectId: string,
138	  channelId: string,
139	  channelName: string,
140	  action: string,
141	  timeblocks: string[] = []
142	): Promise<{ success: boolean; hazard: number; played: number; record: ChannelStateRecord }> {
143	  const currentChannels = await fetchChannelState(projectId);
144	  const chRecord: ChannelStateRecord = currentChannels[channelId] || {
145	    channel_id: channelId,
146	    channel_name: channelName,
147	    score_3_count: [],
148	    score_4_count: [],
149	    score_5_count: [],
150	    score_6_count: [],
151	    score_7_count: [],
152	    timeblock_arc0: 0,
153	    timeblock_arc1: 0,
154	    timeblock_arc2: 0,
155	    timeblock_arc3: 0,
156	    timeblock_arc4: 0,
157	    unlock_date: null,
158	  };
159	
160	  const timestampHex = Date.now().toString(16).toUpperCase();
161	  const act = action.toLowerCase().trim();
162	
163	  if (act === '3+' || act === 'cancel' || act === 'downvote') {
164	    chRecord.score_3_count.push(timestampHex);
165	  } else if (act === '4+') {
166	    chRecord.score_4_count.push(timestampHex);
167	  } else if (act === '5+' || act === 'continue') {
168	    chRecord.score_5_count.push(timestampHex);
169	  } else if (act === '6+' || act === 'upvote') {
170	    chRecord.score_6_count.push(timestampHex);
171	  } else if (act === '7+' || act === 'overflow') {
172	    chRecord.score_7_count.push(timestampHex);
173	  }
174	
175	  if (timeblocks && timeblocks.length > 0) {
176	    timeblocks.forEach((b) => {
177	      if (/arc\s*zero|kick/i.test(b)) chRecord.timeblock_arc0++;
178	      else if (/arc\s*0?1|morning/i.test(b)) chRecord.timeblock_arc1++;
179	      else if (/arc\s*0?2|battle/i.test(b)) chRecord.timeblock_arc2++;
180	      else if (/arc\s*0?3|night/i.test(b)) chRecord.timeblock_arc3++;
181	      else if (/arc\s*0?4|sacred/i.test(b)) chRecord.timeblock_arc4++;
182	    });
183	  }
184	
185	  chRecord.updated_at = new Date().toISOString();
186	
187	  // 1. Upsert into channel_state table in _3_state.db
188	  await executeOrder({
189	    project_id: projectId,
190	    tier: 'channel_state',
191	    order: {
192	      action: 'upsert',
193	      key: channelId,
194	      data: {
195	        channel_name: channelName,
196	        score_3_count: JSON.stringify(chRecord.score_3_count),
197	        score_4_count: JSON.stringify(chRecord.score_4_count),
198	        score_5_count: JSON.stringify(chRecord.score_5_count),
199	        score_6_count: JSON.stringify(chRecord.score_6_count),
200	        score_7_count: JSON.stringify(chRecord.score_7_count),

201	        timeblock_arc0: chRecord.timeblock_arc0,
202	        timeblock_arc1: chRecord.timeblock_arc1,
203	        timeblock_arc2: chRecord.timeblock_arc2,
204	        timeblock_arc3: chRecord.timeblock_arc3,
205	        timeblock_arc4: chRecord.timeblock_arc4,
206	        unlock_date: chRecord.unlock_date,
207	        updated_at: chRecord.updated_at,
208	      },
209	    },
210	  });
211	
212	  // 2. Also record to Tier 2 JSONL event buffer
213	  await executeOrder({
214	    project_id: projectId,
215	    tier: '2',
216	    order: {
217	      action: 'append',
218	      data: {
219	        id: channelId,
220	        target_type: 'channel',
221	        channel_id: channelId,
222	        channel_name: channelName,
223	        action: action,
224	        timestamp: timestampHex,
225	        timeblock: timeblocks.length === 1 ? timeblocks[0] : timeblocks.length > 1 ? timeblocks : undefined,
226	      },
227	    },
228	  });
229	
230	  const hazard = calculateHazardLevel(chRecord);
231	  const played = calculateTotalPlayed(chRecord);
232	
233	  return { success: true, hazard, played, record: chRecord };
234	}
