236	export async function fetchEligibleTier4List(
237	  projectId: string,
238	  forceRefresh = false
239	): Promise<VinylDisplayCard[]> {
240	  if (!forceRefresh && cachedEligibleTier4List) {
241	    return cachedEligibleTier4List;
242	  }
243	
244	  const t4Res = await executeOrder<Record<string, Record<string, unknown>>>({
245	    project_id: projectId,
246	    tier: '4',
247	    order: { action: 'read_all' },
248	  });
249	  const t4Data = t4Res.data || {};
250	
251	  const list: VinylDisplayCard[] = [];
252	  let indexCounter = 1;
253	
254	  for (const [id, rawT4] of Object.entries(t4Data)) {
255	    const t4Item = (rawT4 as Record<string, unknown>) || {};
256	    const rawHazard = t4Item.hazard_level;
257	    const hazard =
258	      rawHazard !== undefined && rawHazard !== null && !isNaN(Number(rawHazard))
259	        ? Number(rawHazard)
260	        : 3.0;
261	
262	    if (hazard <= 3.0) continue;
263	
264	    const rawPlayed = t4Item.played;
265	    const played =
266	      rawPlayed !== undefined && rawPlayed !== null && !isNaN(Number(rawPlayed))
267	        ? Number(rawPlayed)
268	        : 0;
269	
270	    list.push({
271	      id,
272	      dbIndex: indexCounter++,
273	      title: `Track ${id}`,
274	      channel: '',
275	      duration: null,
276	      hazard_level: hazard,
277	      played,
278	      timeblock: (t4Item.timeblock as string) || null,
279	      unlock_date: (t4Item.unlock_date as string) || null,
280	      rankCategory: getRankFromScore(hazard),
281	    });
282	  }
283	
284	  cachedEligibleTier4List = list;
285	  return list;
286	}
