351	export async function resolvePageMetadataOnDemand(
352	  projectId: string,
353	  pageTracks: VinylDisplayCard[]
354	): Promise<VinylDisplayCard[]> {
355	  if (pageTracks.length === 0) return [];
356	
357	  const missingIds = pageTracks
358	    .map((t) => t.id)
359	    .filter((id) => !tier1MemoryCache[id]);
360	
361	  if (missingIds.length > 0) {
362	    try {
363	      const res = await executeOrder<Record<string, Tier1StaticItem>>({
364	        project_id: projectId,
365	        tier: '1',
366	        order: { action: 'batch_read', data: missingIds },
367	      });
368	      const dataMap = res.data || {};
369	      for (const [id, staticInfo] of Object.entries(dataMap)) {
370	        tier1MemoryCache[id] = staticInfo;
371	      }
372	    } catch (e) {
373	      console.warn(`[LazyTier1 Batch] Lỗi tải batch ${missingIds.length} items:`, e);
374	    }
375	  }
376	
377	  return pageTracks.map((item) => {
378	    const staticInfo = tier1MemoryCache[item.id];
379	    return {
380	      ...item,
381	      title: staticInfo?.title || item.title,
382	      channel:
383	        staticInfo?.channel_name ||
384	        staticInfo?.channel ||
385	        staticInfo?.artist ||
386	        'Unknown Origin',
387	      duration: staticInfo?.duration ?? null,
388	    };
389	  });
390	}
