470	export async function syncTier2ToTier3(projectId: string) {
471	  const tier2Res = await executeOrder<Tier2EventEntry[]>({
472	    project_id: projectId,
473	    tier: '2',
474	    order: { action: 'read_all' },
475	  });
476	  const rawEvents = Array.isArray(tier2Res.data) ? tier2Res.data : [];
477	
478	  // 1. Gather all block events from rawEvents
479	  const blockedPayloadMap: Record<string, { id: string; blocked_at: string }> = {};
480	  for (const evt of rawEvents) {
481	    if (!evt || !evt.id) continue;
482	    const act = (evt.action || '').toLowerCase().trim();
483	    if (act === 'block') {
484	      blockedPayloadMap[evt.id] = {
485	        id: evt.id,
486	        blocked_at: evt.timestamp || new Date().toISOString(),
487	      };
488	    }
489	  }
490	
491	  // 2. Persist new block events to blacklist database
492	  if (Object.keys(blockedPayloadMap).length > 0) {
493	    await executeOrder({
494	      project_id: projectId,
495	      tier: 'blacklist',
496	      order: {
497	        action: 'batch_upsert',
498	        data: blockedPayloadMap,
499	      },
500	    });
501	  }
502	
503	  // 3. Fetch all excluded IDs across blacklist AND bad_kpi
504	  const [blacklistRes, badKpiRes] = await Promise.all([
505	    executeOrder<Record<string, Record<string, unknown>>>({
506	      project_id: projectId,
507	      tier: 'blacklist',
508	      order: { action: 'read_all' },
509	    }),
510	    executeOrder<Record<string, Record<string, unknown>>>({
511	      project_id: projectId,
512	      tier: 'bad_kpi',
513	      order: { action: 'read_all' },
514	    }),
515	  ]);
516	
517	  const allExcludedIds = Array.from(
518	    new Set([
519	      ...Object.keys(blockedPayloadMap),
520	      ...Object.keys(blacklistRes.data || {}),
521	      ...Object.keys(badKpiRes.data || {}),
522	    ])
523	  );
524	
525	  // 4. Purge all excluded IDs from Tier 3 (_3_state.db) and Tier 4 (_4_display.db)
526	  if (allExcludedIds.length > 0) {
527	    await Promise.all([
528	      executeOrder({
529	        project_id: projectId,
530	        tier: '3',
531	        order: { action: 'batch_delete', data: allExcludedIds },
532	      }),
533	      executeOrder({
534	        project_id: projectId,
535	        tier: '4',
536	        order: { action: 'batch_delete', data: allExcludedIds },
537	      }),
538	    ]);
539	  }
540	
541	  // 5. Purge from Tier 1 (_1_static.db)
542	  let staticSynced = false;
543	  try {
544	    await syncRawinfoMinusBlacklistToTier1(projectId);
545	    staticSynced = true;
546	  } catch (e) {
547	    console.error('[Blacklist->Static] Lỗi trừ ID khỏi _1_static.db:', e);
548	  }
549	
550	  // 6. Process non-blocked rating events for Tier 3 tracks and channels
551	  const excludedSet = new Set(allExcludedIds);
552	  const [currentT3, currentChannels] = await Promise.all([
553	    fetchTier3State(projectId),
554	    fetchChannelState(projectId),
555	  ]);
556	
557	  const stateMap: Record<string, Tier3StateRecord> = {};
558	  currentT3.forEach((r) => {
559	    if (!excludedSet.has(r.id)) {
560	      stateMap[r.id] = r;
561	    }
562	  });
563	
564	  const channelMap: Record<string, ChannelStateRecord> = { ...currentChannels };
565	  const modifiedTrackIds = new Set<string>();
566	  const modifiedChannelIds = new Set<string>();
567	
568	  for (const evt of rawEvents) {
569	    if (!evt || !evt.id || excludedSet.has(evt.id)) continue;
570	    const act = (evt.action || '').toLowerCase().trim();

571	    if (act === 'block') continue;
572	
573	    // Check if event is targeted to an entire channel
574	    if (evt.target_type === 'channel' || (evt.channel_id && evt.channel_id === evt.id)) {
575	      const chId = evt.channel_id || evt.id;
576	      if (!channelMap[chId]) {
577	        channelMap[chId] = {
578	          channel_id: chId,
579	          channel_name: evt.channel_name || '',
580	          score_3_count: [],
