750	export async function syncTier3ToTier4(projectId: string) {
751	  // Fetch full blacklist and bad_kpi to strictly prevent them in Tier 4
752	  const [blacklistRes, badKpiRes] = await Promise.all([
753	    executeOrder<Record<string, Record<string, unknown>>>({
754	      project_id: projectId,
755	      tier: 'blacklist',
756	      order: { action: 'read_all' },
757	    }),
758	    executeOrder<Record<string, Record<string, unknown>>>({
759	      project_id: projectId,
760	      tier: 'bad_kpi',
761	      order: { action: 'read_all' },
762	    }),
763	  ]);
764	
765	  const excludedIds = Array.from(
766	    new Set([
767	      ...Object.keys(blacklistRes.data || {}),
768	      ...Object.keys(badKpiRes.data || {}),
769	    ])
770	  );
771	  const excludedSet = new Set(excludedIds);
772	
773	  const [t3Records, channelRecords] = await Promise.all([
774	    fetchTier3State(projectId),
775	    fetchChannelState(projectId),
776	  ]);
777	
778	  const badKpiMap: Record<string, { id: string; hazard_level: number; purged_at: string }> = {};
779	  const t4ValidBatchMap: Record<string, Record<string, unknown>> = {};
780	  const t3PurgeIds: string[] = [];
781	
782	  // Index individual track ratings
783	  const trackMap: Record<string, Tier3StateRecord> = {};
784	  for (const t3 of t3Records) {
785	    if (excludedSet.has(t3.id)) {
786	      t3PurgeIds.push(t3.id);
787	      continue;
788	    }
789	    trackMap[t3.id] = t3;
790	  }
791	
792	  // Fetch track lists for rated channels to apply channel-wide metadata
793	  const activeChannelIds = Object.keys(channelRecords).filter((id) => !excludedSet.has(id));
794	  const channelTracksMap: Record<string, string[]> = {};
795	
796	  if (activeChannelIds.length > 0) {
797	    try {
798	      const chTracksRes = await executeOrder<Record<string, string[]>>({
799	        project_id: projectId,
800	        tier: '1',
801	        order: {
802	          action: 'get_channel_tracks',
803	          data: { channel_ids: activeChannelIds },
804	        },
805	      });
806	      if (chTracksRes.data) {
807	        Object.assign(channelTracksMap, chTracksRes.data);
808	      }
809	    } catch (e) {
810	      console.warn('[syncTier3ToTier4] Error fetching channel tracks:', e);
811	    }
812	  }
813	
814	  const processedSongIds = new Set<string>();
815	
816	  // Process all songs belonging to rated channels (channel metadata applies to every song of that channel)
817	  for (const chId of activeChannelIds) {
818	    const ch = channelRecords[chId];
819	    const songsInChannel = channelTracksMap[chId] || [];
820	
821	    for (const songId of songsInChannel) {
822	      if (excludedSet.has(songId)) continue;
823	      processedSongIds.add(songId);
824	
825	      const individualT3 = trackMap[songId];
826	      let compositeRecord: Tier3StateRecord;
827	
828	      if (individualT3) {
829	        compositeRecord = {
830	          id: songId,
831	          score_3_count: [...ch.score_3_count, ...individualT3.score_3_count],
832	          score_4_count: [...ch.score_4_count, ...individualT3.score_4_count],
833	          score_5_count: [...ch.score_5_count, ...individualT3.score_5_count],
834	          score_6_count: [...ch.score_6_count, ...individualT3.score_6_count],
835	          score_7_count: [...ch.score_7_count, ...individualT3.score_7_count],
836	          timeblock_arc0: ch.timeblock_arc0 + individualT3.timeblock_arc0,
837	          timeblock_arc1: ch.timeblock_arc1 + individualT3.timeblock_arc1,
838	          timeblock_arc2: ch.timeblock_arc2 + individualT3.timeblock_arc2,
