840	          timeblock_arc4: ch.timeblock_arc4 + individualT3.timeblock_arc4,
841	          unlock_date: individualT3.unlock_date || ch.unlock_date,
842	          hazard_rank: individualT3.hazard_rank ?? null,
843	        };
844	      } else {
845	        compositeRecord = {
846	          id: songId,
847	          score_3_count: [...ch.score_3_count],
848	          score_4_count: [...ch.score_4_count],
849	          score_5_count: [...ch.score_5_count],
850	          score_6_count: [...ch.score_6_count],
851	          score_7_count: [...ch.score_7_count],
852	          timeblock_arc0: ch.timeblock_arc0,
853	          timeblock_arc1: ch.timeblock_arc1,
854	          timeblock_arc2: ch.timeblock_arc2,
855	          timeblock_arc3: ch.timeblock_arc3,
856	          timeblock_arc4: ch.timeblock_arc4,
857	          unlock_date: ch.unlock_date,
858	          hazard_rank: null,
859	        };
860	      }
861	
862	      if (compositeRecord.hazard_rank) {
863	        const hazard = calculateHazardLevel(compositeRecord);
864	        t4ValidBatchMap[songId] = {
865	          id: songId,
866	          hazard_level: hazard,
867	          played: calculateTotalPlayed(compositeRecord),
868	          timeblock: getDominantTimeblock(compositeRecord),
869	          unlock_date: compositeRecord.unlock_date,
870	        };

871	      }
872	    }
873	  }
874	
875	  // Process remaining individual track ratings whose channels weren't batch rated
876	  for (const t3 of t3Records) {
877	    if (processedSongIds.has(t3.id) || excludedSet.has(t3.id)) continue;
878	
879	    if (t3.hazard_rank) {
880	      const hazard = calculateHazardLevel(t3);
881	      t4ValidBatchMap[t3.id] = {
882	        id: t3.id,
883	        hazard_level: hazard,
884	        played: calculateTotalPlayed(t3),
885	        timeblock: getDominantTimeblock(t3),
886	        unlock_date: t3.unlock_date,
887	      };
888	    }
889	  }
890	
891	  // Delete any excluded tracks that were lingering in Tier 3 or Tier 4
892	  const combinedPurgeIds = Array.from(new Set([...t3PurgeIds, ...excludedIds]));
893	  if (combinedPurgeIds.length > 0) {
894	    await Promise.all([
895	      executeOrder({
896	        project_id: projectId,
897	        tier: '3',
898	        order: { action: 'batch_delete', data: combinedPurgeIds },
899	      }),
900	      executeOrder({
