909	    await executeOrder({
910	      project_id: projectId,
911	      tier: '4',
912	      order: {
913	        action: 'batch_upsert',
914	        data: t4ValidBatchMap,
915	      },
916	    });
917	  }
918	
919	  const badKpiIds = Object.keys(badKpiMap);
920	  if (badKpiIds.length > 0) {
921	    await Promise.all([
922	      executeOrder({
923	        project_id: projectId,
924	        tier: '4',
925	        order: { action: 'batch_delete', data: badKpiIds },
926	      }),
927	      executeOrder({
928	        project_id: projectId,
929	        tier: '3',
930	        order: { action: 'batch_delete', data: badKpiIds },
931	      }),
932	      executeOrder({
933	        project_id: projectId,
934	        tier: 'bad_kpi',
935	        order: { action: 'batch_upsert', data: badKpiMap },
936	      }),
937	    ]);
938	
939	    try {
940	      await syncRawinfoMinusBlacklistToTier1(projectId);
941	    } catch (e) {
942	      console.error('[BadKPI->Static] Lỗi lọc ID khỏi _1_static.db:', e);
943	    }
944	  }
945	
946	  invalidateVinylCache(projectId);
947	  return {
948	    syncedCount: Object.keys(t4ValidBatchMap).length,
949	    purgedCount: badKpiIds.length + t3PurgeIds.length,
950	    badKpiIds,
951	  };
