1004	      tier: '4',
1005	      order: { action: 'read_all' },
1006	    }),
1007	    fetchChannelState(projectId),
1008	  ]);
1009	
1010	  const statsMap: Record<string, import('../types').TrackDisplayMeta> = {};
1011	  if (t4Res.data) {
1012	    Object.entries(t4Res.data).forEach(([id, val]) => {
1013	      let played = 0;
1014	      let hazard_level = 3.0;
1015	      let timeblock: string | null = null;
1016	      let unlock_date: string | null = null;
1017	
1018	      if (val && typeof val === 'object' && !Array.isArray(val)) {
1019	        const v = val as Record<string, unknown>;
1020	        played = Number.isInteger(v.played)

1021	          ? (v.played as number)
1022	          : parseInt(String(v.played || 0), 10);
1023	        const rawHazard = Number(v.hazard_level);
1024	        hazard_level = !isNaN(rawHazard) ? rawHazard : 3.0;
1025	        timeblock = (v.timeblock as string) || null;
1026	        unlock_date = (v.unlock_date as string) || null;
1027	      } else if (val !== null && val !== undefined) {
1028	        played = parseInt(String(val), 10);
1029	      }
1030	
1031	      statsMap[String(id)] = {
1032	        played: Number.isFinite(played) && played >= 0 ? Math.floor(played) : 0,
1033	        hazard_level: Math.round(hazard_level * 100) / 100,
1034	        timeblock,
1035	        unlock_date,
1036	      };
1037	    });
1038	  }
1039	
1040	  const rawSample = sampleRes.data || {};
1041	  const sampleTrackIds = Object.keys(rawSample).map(String);
1042	  const hazardRankMap: Record<string, number | null> = {};
1043	  if (sampleTrackIds.length > 0) {
1044	    try {
1045	      const t3Res = await executeOrder<Record<string, Record<string, unknown>>>({
