1053	            hazardRankMap[id] = Number(r.hazard_rank);
1054	          }
1055	        });
1056	      }
1057	    } catch (_) {}
1058	  }
1059	
1060	  const tracks: PlaylistItem[] = Object.entries(rawSample)
1061	    .map(([id, val]) => {
1062	      const v = (val as Record<string, unknown>) || {};
1063	      const trackId = String(id).trim();
1064	      const t4 = statsMap[trackId];
1065	      const chId = (v.channel_id as string) || (v.channelId as string) || '';
1066	      const chState = chId ? channelStateMap[chId] : undefined;
