1072	      const effectiveHazard = t4 ? t4.hazard_level : chHazard;
1073	      const effectivePlayed = t4 ? t4.played : chPlayed;
1074	      const effectiveTimeblock = t4?.timeblock ?? chTimeblock;
1075	      const effectiveRank = hazardRankMap[trackId] ?? null;
1076	
1077	      // Update statsMap so track stats are populated
1078	      if (!t4 && chState) {
1079	        statsMap[trackId] = {
1080	          hazard_level: effectiveHazard,
1081	          played: effectivePlayed,
1082	          timeblock: effectiveTimeblock,
1083	          unlock_date: chState.unlock_date,
1084	          hazard_rank: effectiveRank,
1085	        };
1086	      } else if (statsMap[trackId]) {
1087	        statsMap[trackId].hazard_rank = effectiveRank;
1088	      }
1089	
1090	      return {
1091	        id: trackId,
1092	        title: (v.title as string) || (v.name as string) || `Track ${id}`,
1093	        channel:
