1099	        duration: (v.duration as number) ?? null,
1100	        hazard_level: effectiveHazard,
1101	        played: effectivePlayed,
1102	        timeblock: effectiveTimeblock,
1103	        hazard_rank: effectiveRank,
1104	      };
1105	    })
1106	    .filter((t) => t.id && t.id.length >= 8);
1107	
1108	  const totalCatalogCount = countRes.data?.count !== undefined ? countRes.data.count : tracks.length;
1109	
1110	  return { tracks, totalCatalogCount, statsMap };
1111	}
