1348	  },
1349	  onEvent: (event: CurlerStreamEvent) => void,
1350	  signal?: AbortSignal
1351	): Promise<void> {
1352	  const res = await fetch(`${API_BASE}/api/v1/curler/stream`, {
1353	    method: 'POST',
1354	    headers: { 'Content-Type': 'application/json' },
1355	    body: JSON.stringify(options),
1356	    signal,
1357	  });
1358	
1359	  if (!res.ok) {
1360	    throw new Error(`Curler stream request failed with HTTP ${res.status}`);
1361	  }
1362	
1363	  if (!res.body) {
1364	    throw new Error('ReadableStream not supported on response body.');
1365	  }
1366	
1367	  const reader = res.body.getReader();
1368	  const decoder = new TextDecoder('utf-8');
1369	  let buffer = '';
1370	
1371	  while (true) {
1372	    const { done, value } = await reader.read();
1373	    if (done) break;
1374	
1375	    buffer += decoder.decode(value, { stream: true });
1376	    const chunks = buffer.split('\n\n');
1377	    buffer = chunks.pop() || '';
1378	
1379	    for (const chunk of chunks) {
1380	      const trimmed = chunk.trim();

1380	      const trimmed = chunk.trim();
1381	      if (trimmed.startsWith('data:')) {
1382	        try {
1383	          const jsonStr = trimmed.slice(5).trim();
