1391	      }
1392	    }
1393	  }
1394	
1395	  if (buffer.trim().startsWith('data:')) {
1396	    try {
1397	      const jsonStr = buffer.trim().slice(5).trim();
1398	      if (jsonStr) {
1399	        const eventData = JSON.parse(jsonStr) as CurlerStreamEvent;
1400	        onEvent(eventData);
1401	      }
